import { createContext, useContext, useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const AuthContext = createContext();

export const useAuth = () => useContext(AuthContext);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    // Check for token on mount
    const token = localStorage.getItem('ehr_token');
    const role = localStorage.getItem('ehr_role');
    const username = localStorage.getItem('ehr_username');

    if (token && role && username) {
      setUser({ token, role, username });
    }
    setLoading(false);
  }, []);

  const login = (token, role, username) => {
    localStorage.setItem('ehr_token', token);
    localStorage.setItem('ehr_role', role);
    localStorage.setItem('ehr_username', username);
    setUser({ token, role, username });
    navigate('/dashboard');
  };

  const logout = () => {
    localStorage.removeItem('ehr_token');
    localStorage.removeItem('ehr_role');
    localStorage.removeItem('ehr_username');
    setUser(null);
    navigate('/login');
  };

  return (
    <AuthContext.Provider value={{ user, login, logout, loading }}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

import { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { motion } from 'framer-motion';
import { ShieldPlus, CheckCircle2, ArrowRight } from 'lucide-react';

export default function AuthPortal() {
  const [isLogin, setIsLogin] = useState(true);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('patient');
  const [error, setError] = useState('');

  const { login } = useAuth();

  const API_URL = 'http://127.0.0.1:5000';

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    try {
      const endpoint = isLogin ? '/login' : '/register';
      const body = isLogin ? { username, password } : { username, password, role };

      const res = await fetch(`${API_URL}${endpoint}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body)
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.message || data.error || 'Authentication failed');
      }

      if (isLogin) {
        login(data.token, data.role, data.username);
      } else {
        setIsLogin(true);
        setError('Registration successful! Please log in.'); // Actually using error state to show success temporarily
        setPassword('');
      }
    } catch (err) {
      setError(err.message);
    }
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '2rem' }}>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(360px, 1fr))', gap: '3rem', maxWidth: '1000px', width: '100%' }}>

        <motion.div 
          initial={{ opacity: 0, x: -30 }} 
          animate={{ opacity: 1, x: 0 }}
          style={{
            background: 'linear-gradient(155deg, rgba(143,224,201,0.30) 0%, rgba(179,192,245,0.28) 50%, rgba(255,196,168,0.22) 100%)',
            backdropFilter: 'var(--blur)',
            WebkitBackdropFilter: 'var(--blur)',
            borderRadius: 'var(--r-lg)',
            padding: '3rem',
            border: '1px solid rgba(255,255,255,0.6)',
            boxShadow: 'var(--s-md)',
            position: 'relative',
            overflow: 'hidden'
          }}
        >
          <ShieldPlus size={44} style={{ color: 'var(--accent)', marginBottom: '1.5rem'}} />
          <h1 style={{ fontSize: '2.5rem', marginBottom: '0.2rem' }}>
            <span className="gradient-text">HealthChain AI</span>
          </h1>
          <p style={{  fontSize: '0.78rem', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.10em', color: 'var(--t2)', marginBottom: '1.2rem' }}>
            Decentralized Electronic Health Records
          </p>
          <div style={{ width: '40px', height: '3px', background: 'linear-gradient(90deg, #5FC2A8, #8C9EED)', borderRadius: '99px', marginBottom: '1.5rem' }}></div>
          <p style={{ color: 'var(--t2)', lineHeight: 1.7, marginBottom: '2rem' }}>
            Enterprise-grade clinical EHR powered by Scikit-Learn ML, Hyperledger Fabric smart contracts, and IPFS distributed storage.
          </p>
          <ul style={{ listStyle: 'none', padding: 0, display: 'flex', flexDirection: 'column', gap: '1rem' }}>
            {['Patient-controlled permissions via Smart Contracts', 'Automated Gradient Boosting predictive analysis', 'Immutable medical file hosting on IPFS node networks'].map((text, i) => (
              <li key={i} style={{ display: 'flex', alignItems: 'center', gap: '10px', fontSize: '0.9rem', color: 'var(--t1)' }}>
                <CheckCircle2 size={18} style={{ color: 'var(--accent)' }} />
                {text}
              </li>
            ))}
          </ul>
        </motion.div>

        <motion.div 
          initial={{ opacity: 0, x: 30 }} 
          animate={{ opacity: 1, x: 0 }}
          style={{ display: 'flex', flexDirection: 'column', justifyContent: 'center' }}
        >
          <div style={{ display: 'flex', background: 'rgba(255,255,255,0.45)', backdropFilter: 'var(--blur-sm)', padding: '4px', borderRadius: '12px', border: '1px solid var(--glass-border)', marginBottom: '2rem', gap:'4px' }}>
            <button 
              onClick={() => setIsLogin(true)}
              style={{ flex: 1, padding: '0.6rem', borderRadius: '8px', border: 'none', background: isLogin ? 'rgba(255,255,255,0.9)' : 'transparent', color: isLogin ? 'var(--accent)' : 'var(--t2)', fontWeight: isLogin ? 600 : 500, boxShadow: isLogin ? 'var(--s-xs)' : 'none', cursor: 'pointer', transition: 'all 0.2s' }}
            >Log In</button>
            <button 
              onClick={() => setIsLogin(false)}
              style={{ flex: 1, padding: '0.6rem', borderRadius: '8px', border: 'none', background: !isLogin ? 'rgba(255,255,255,0.9)' : 'transparent', color: !isLogin ? 'var(--accent)' : 'var(--t2)', fontWeight: !isLogin ? 600 : 500, boxShadow: !isLogin ? 'var(--s-xs)' : 'none', cursor: 'pointer', transition: 'all 0.2s' }}
            >Sign Up</button>
          </div>

          <div className="glass-panel" style={{ padding: '2rem' }}>
            <h2 style={{ fontSize: '1.45rem', marginBottom: '0.2rem' }}>Portal Access</h2>
            <p style={{ fontSize: '0.9rem', color: 'var(--t2)', marginBottom: '1.5rem' }}>
              {isLogin ? 'Log in to authenticate your node keys' : 'Register a new identity on the network'}
            </p>

            {error && (
              <div style={{ background: error.includes('success') ? 'rgba(143,224,201,0.2)' : 'rgba(214,69,69,0.1)', borderLeft: \`4px solid \${error.includes('success') ? 'var(--accent)' : 'var(--high)'}\`, padding: '1rem', borderRadius: 'var(--r-sm)', marginBottom: '1.5rem', fontSize: '0.9rem', color: 'var(--t1)' }}>
                {error}
              </div>
            )}

            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1.2rem' }}>
              <div>
                <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 600, fontSize: '0.9rem' }}>Username Identifier</label>
                <input required type="text" className="input-glass" placeholder="e.g. doctor_smith" value={username} onChange={e => setUsername(e.target.value)} />
              </div>
              <div>
                <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 600, fontSize: '0.9rem' }}>Security Key</label>
                <input required type="password" className="input-glass" placeholder="••••••••" value={password} onChange={e => setPassword(e.target.value)} />
              </div>

              {!isLogin && (
                <div>
                  <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 600, fontSize: '0.9rem' }}>Network Role</label>
                  <select className="input-glass" value={role} onChange={e => setRole(e.target.value)} style={{ appearance: 'none' }}>
                    <option value="patient">Patient Node</option>
                    <option value="doctor">Doctor Node</option>
                    <option value="admin">Admin Node</option>
                  </select>
                </div>
              )}

              <button type="submit" className="btn-primary" style={{ marginTop: '0.5rem' }}>
                {isLogin ? 'Authenticate Identity' : 'Register Node'} <ArrowRight size={18}/>
              </button>
            </form>
          </div>
        </motion.div>

      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import Sidebar from '../components/Sidebar';
import { motion } from 'framer-motion';
import { FileText, Loader2, Download, Search, HeartPulse } from 'lucide-react';

export default function Dashboard() {
  const { user } = useAuth();
  const [records, setRecords] = useState([]);
  const [loading, setLoading] = useState(true);

  const API_URL = 'http://127.0.0.1:5000';

  useEffect(() => {
    if (!user) return;
    fetchRecords();
  }, [user]);

  const fetchRecords = async () => {
    try {
      const endpoint = user.role === 'patient' ? '/get_my_records' : '/get_records_by_doctor';
      const res = await fetch(`${API_URL}${endpoint}`, {
        headers: { 'Authorization': `Bearer ${user.token}` }
      });
      const data = await res.json();
      setRecords(data || []);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleDownload = async (recordId) => {
    try {
      const res = await fetch(`${API_URL}/download_report/${recordId}`, {
        headers: { 'Authorization': `Bearer ${user.token}` }
      });
      if (res.ok) {
        const blob = await res.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `report_${recordId}.pdf`;
        a.click();
      }
    } catch (err) {
      console.error('Download failed', err);
    }
  };

  const parsePrediction = (predString) => {
    try {
      if (typeof predString === 'object') return predString;
      return JSON.parse(predString);
    } catch {
      return { prediction: predString, risk_level: 'Unknown', timestamp: 'N/A' };
    }
  };

  return (
    <div className="app-container">
      <Sidebar />
      <main className="main-content">
        <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: '2.5rem' }}>
            <div>
              <h1 style={{ fontSize: '2rem', marginBottom: '0.2rem' }}>Welcome, {user.username}</h1>
              <p>Your decentralized health portal overview.</p>
            </div>
            {user.role === 'doctor' && (
              <button className="btn-primary" style={{ padding: '0.6rem 1.2rem' }}>
                <HeartPulse size={18} /> New Prediction
              </button>
            )}
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: '1.5rem', marginBottom: '3rem' }}>
            <div className="glass-panel" style={{ padding: '1.5rem' }}>
              <p style={{ color: 'var(--t3)', textTransform: 'uppercase', fontSize: '0.75rem', fontWeight: 700, letterSpacing: '0.05em' }}>Total Records</p>
              <h2 style={{ fontSize: '2.5rem', margin: '0.5rem 0', fontFamily: 'var(--font-h1)' }} className="gradient-text">{records.length}</h2>
              <p style={{ fontSize: '0.85rem' }}>Available on blockchain</p>
            </div>
            {/* Add more metric cards if needed */}
          </div>

          <h2 style={{ marginBottom: '1.5rem' }}>Medical History Ledger</h2>

          {loading ? (
            <div style={{ display: 'flex', justifyContent: 'center', padding: '3rem' }}>
              <Loader2 className="spinner" size={32} style={{ animation: 'spin 1s linear infinite', color: 'var(--accent)' }}/>
            </div>
          ) : records.length === 0 ? (
            <div className="glass-panel" style={{ padding: '3rem', textAlign: 'center' }}>
              <FileText size={48} style={{ color: 'var(--t3)', margin: '0 auto 1rem', opacity: 0.5 }} />
              <h3>No records found</h3>
              <p>No historical records are attached to your node address.</p>
            </div>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
              {records.map((rec) => {
                const mlData = parsePrediction(rec.mlPrediction);
                const isHighRisk = mlData.risk_level?.toLowerCase().includes('high');

                return (
                  <div key={rec.id} className="glass-panel" style={{ padding: '1.5rem', display: 'flex', alignItems: 'center', justifyContent: 'space-between', borderLeft: `4px solid ${isHighRisk ? 'var(--high)' : 'var(--low)'}` }}>
                    <div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '0.5rem' }}>
                        <h3 style={{ fontSize: '1.1rem' }}>{rec.patientId}&apos;s Report</h3>
                        <span className={`badge ${isHighRisk ? 'badge-high' : 'badge-low'}`}>
                          {mlData.risk_level || 'Evaluated'}
                        </span>
                      </div>
                      <p style={{ fontSize: '0.85rem', color: 'var(--t3)' }}>
                        <strong style={{ color: 'var(--t2)' }}>Diagnosis:</strong> {mlData.prediction} &bull; 
                        <strong style={{ color: 'var(--t2)', marginLeft: '8px' }}>Date:</strong> {mlData.timestamp}
                      </p>
                    </div>
                    <div style={{ display: 'flex', gap: '0.5rem' }}>
                      <button className="btn-secondary" onClick={() => handleDownload(rec.id)} style={{ padding: '0.5rem 1rem', fontSize: '0.85rem' }}>
                        <Download size={16} /> PDF Report
                      </button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </motion.div>
      </main>
      <style>{`
        @keyframes spin { 100% { transform: rotate(360deg); } }
      `}</style>
    </div>
  );
}
